INSERT INTO jobs_public (company, title, city, job_type, industry, education, salary, source, url, jd_text, tags, deadline, posted_at) VALUES (E'美团', E'AI全栈工程师', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'AI全栈工程师\n稀缺\n应届\n北京市、上海市、成都市、深圳市\n更新于2026/08/17\n岗位职责\n岗位职责\n1. 参与 AI 应用的全栈开发：负责 AI 产品功能的前端界面（Web/小程序）与后端服务的设计与实现，保障高可用与用户体验；', NULL, NULL, E'2026-09-23'), (E'美团', E'AI后端开发工程师', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'AI后端开发工程师\n稀缺\n应届\n北京市、上海市、成都市\n更新于2026/08/17\n岗位职责\n1. 负责各类后台服务和业务系统的需求分析、系统设计、开发实现；\n2. 参与后端模块、数据平台、基础服务等的开发工作，探索大模型能力（如LLM API调用、RAG检索增强、AI Agent编排等）在业务系统中的集成与落地；', NULL, NULL, E'2026-09-23'), (E'美团', E'智能商业分析师（BA/DS）', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'智能商业分析师（BA/DS）\n稀缺\n应届\n北京市、上海市\n更新于2026/08/17\n岗位职责\n1. 参与业务规划、策略制定、经营分析，为复杂的商业问题设计解决方案；\n2. 使用一流的数据分析工具和技能，洞察商业规律、用户需求，为业务出谋划策；', NULL, NULL, E'2026-09-23'), (E'美团', E'AI产品经理岗', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'AI产品经理岗\n稀缺\n应届\n北京市、上海市、成都市、深圳市\n更新于2026/08/17\n岗位职责\n1. 迎接多样化的产品研发和运营实战的挑战，产品岗位类型包含功能产品、策略产品、数据产品、工具产品、硬件产品等，覆盖AI驱动产品创新、大模型应用落地等前沿方向；\n2. 从复杂的业务场景/数据中挖掘用户痛点和本质需求，探索AI技术在产品中的应用机会，以结果为导向，推动产品的优化和发展；', NULL, NULL, E'2026-09-23'), (E'美团', E'AI产品运营岗', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'AI产品运营岗\n稀缺\n应届\n北京市、科威特城、上海市、深圳市\n更新于2026/08/17\n岗位职责\n【岗位职责】\n在这里你有机会参与美团的各类运营岗位，可以全方位感受运营的魅力！如果你对以下任意一个方向感兴趣，欢迎网申这个岗位。', NULL, NULL, E'2026-09-23'), (E'美团', E'Nonfood Category Performance Intern', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'Nonfood Category Performance Intern\n日常实习\n北京市\n更新于2026/09/23\n食杂零售-Keemart\n岗位职责\nKey Responsibilities\n1- Category Performance Reporting & Analytics', NULL, NULL, E'2026-09-23'), (E'美团', E'用户研究（实习生）', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'用户研究（实习生）\n日常实习\n北京市\n更新于2026/09/23\n软硬件服务-骑行事业部\n岗位职责\n1.用户研究全链路实践\n* 独立/协作完成用户调研方案设计（问卷、访谈、可用性测试等），负责从研究设计到报告输出的完整闭环', NULL, NULL, E'2026-09-23'), (E'美团', E'大模型算法实习生', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'大模型算法实习生\n日常实习\n北京市\n更新于2026/09/23\n核心本地商业-基础研发平台\n岗位职责\n1. 后训练研究：深入参与模型对齐工作，重点研究多种后训练算法；探索结果奖励和过程奖励模型的构建，提升模型在复杂逻辑下的推理能力。\n2. Agentic RL优化：针对复杂业务场景，优化 Agent 的任务规划、反思与执行能力；提升模型在长链路任务中的稳定性和成功率。', NULL, NULL, E'2026-09-23'), (E'美团', E'美团-C 端AI 产品实习生', E'上海', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'美团-C 端AI 产品实习生\n日常实习\n上海市\n更新于2026/09/23\n核心本地商业-基础研发平台\n岗位职责\n岗位职责：\n1. ﻿﻿负责AI原生应用产品的调研和用户需求收集，参与部分产品模块的功能设计；', NULL, NULL, E'2026-09-23'), (E'美团', E'大模型应用实习生（服务智能）', E'北京', E'校招', E'互联网', NULL, NULL, E'官网投递', NULL, E'大模型应用实习生（服务智能）\n日常实习\n北京市、上海市\n更新于2026/09/23\n核心本地商业-基础研发平台\n岗位职责\n团队介绍： LongCat Interaction 团队负责智能交互系统的研发与落地。团队依托 LLM 与多智能体架构，打造了WOWService 平台，为美团 App 数亿用户提供高效、个性化、7×24 小时的智能客服服务。在这个团队，我们专注于大模型训练与推理优化，让机器能够理解复杂用户意图、遵守业务规则、主动协作解决问题；我们建设自动化评测体系，用数据飞轮驱动模型持续进化；我们构建multi-agent协同框架，实现跨场景、跨部门的复杂任务处理。我们的使命：用大模型的能力，让每一位用户都能获得即时、准确、温暖的解决方案。', NULL, NULL, E'2026-09-23');
